using System;using System.Data;using System.Drawing;using System.Windows.Forms;
namespace AshkanHotelManager{public partial class GlobalSearchForm:Form{TextBox q;DataGridView grid;public GlobalSearchForm(string initial=""){InitializeComponent();Text=App.Persian?"جستجوی سراسری":"Global Search";BackColor=Ui.Bg;Build();q.Text=initial;Search();App.ApplyDirection(this);}void Build(){var top=Ui.SurfacePanel();top.Dock=DockStyle.Top;top.Height=92;q=new TextBox{Width=560,Height=36,Location=new Point(22,25),Font=Ui.Font(11)};q.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter)Search();};var b=Ui.Btn(App.T("search"));b.Width=120;b.Location=new Point(600,20);b.Click+=(s,e)=>Search();top.Controls.AddRange(new Control[]{q,b});Controls.Add(top);grid=new DataGridView{Dock=DockStyle.Fill};Ui.Grid(grid);grid.CellFormatting+=(s,e)=>Ui.FormatStatusCell(grid,e);Controls.Add(grid);grid.BringToFront();top.BringToFront();}void Search(){var t=new DataTable();t.Columns.Add(App.Persian?"بخش":"Section");t.Columns.Add(App.Persian?"عنوان":"Title");t.Columns.Add(App.Persian?"جزئیات":"Details");string s=(q.Text??"").Trim();if(s.Length>0){Find(t,"Rooms","Number","Type",s,App.T("rooms"));Find(t,"Guests","FullName","Phone",s,App.T("guests"));Find(t,"Reservations","Guest","Room",s,App.T("reservations"));}grid.DataSource=t;}void Find(DataTable outTable,string table,string main,string detail,string s,string section){foreach(DataRow r in DataStore.Db.Tables[table].Rows){string a=Convert.ToString(r[main]),b=Convert.ToString(r[detail]);if(a.IndexOf(s,StringComparison.OrdinalIgnoreCase)>=0||b.IndexOf(s,StringComparison.OrdinalIgnoreCase)>=0)outTable.Rows.Add(section,a,b);}}}}
